function mostItemsLoaded(boxKinds: number[][], capacity: number): number {
  const kinds = [...boxKinds].sort((a, b) => b[1] - a[1]);
  let left = capacity, total = 0;
  for (const [count, per] of kinds) {
    const take = Math.min(count, left);
    total += take * per;
    left -= take;
    if (left === 0) break;
  }
  return total;
}

