class Solution:
    def mostItemsLoaded(self, boxKinds: List[List[int]], capacity: int) -> int:
        total, left = 0, capacity
        for count, per in sorted(boxKinds, key=lambda b: -b[1]):
            take = min(count, left)
            total += take * per
            left -= take
            if left == 0:
                break
        return total

