function mostItemsLoaded(boxKinds: number[][], capacity: number): number {
  const boxes = new Array(1001).fill(0);
  for (const [count, per] of boxKinds) boxes[per] += count;
  let left = capacity, total = 0;
  for (let per = 1000; per >= 1 && left > 0; per--) {
    const take = Math.min(boxes[per], left);
    total += take * per;
    left -= take;
  }
  return total;
}

